<script>
 import {Root,DialogBackdrop,DialogContent,Positioner,Title} from '@ark-ui/svelte/dialog'
 import {Portal} from '@ark-ui/svelte/portal'
 import Button from '../Button.svelte'
 import Icon from '../Icon.svelte'
 /** @type {{references?:readonly {id:string,label:string,subjectName?:string,subject?:{kind:string},roles?:readonly string[]}[],selected?:readonly {referenceId:string,role:string}[],imageURLs?:Record<string,string>,oninspect?:(id:string)=>void,onchoose?:(id:string,role:string)=>void,onclose?:()=>void}} */
 let {references=[],selected=[],imageURLs={},oninspect=undefined,onchoose=undefined,onclose=undefined}=$props()
 let search=$state(''),id=$state('')
 const rows=$derived(references.filter(r=>(r.label+' '+(r.subjectName??'')).toLowerCase().includes(search.toLowerCase())))
 const current=$derived(references.find(r=>r.id===id))
 const roleLabel={prop:'Match prop',set:'Match place',identity:'Match identity',detail:'Use details',style:'Use style',layout:'Use layout'}
</script>
<Root open lazyMount unmountOnExit onOpenChange={d=>{if(!d.open)onclose?.()}}>
 <Portal>
 <DialogBackdrop class="ui-ref-picker__backdrop" />
 <Positioner class="ui-ref-picker__positioner"><DialogContent class="ui-ref-picker__dialog">
  <header class="ui-ref-picker__header"><Title class="ui-ref-picker__title">Project image references</Title><Button variant="tool" icon="x" onclick={()=>onclose?.()}>Close</Button></header>
  <div class="ui-ref-picker__body">
   <div class="ui-ref-picker__library"><input type="search" aria-label="Search project image references" placeholder="Search subject or image" bind:value={search} /><div class="ui-ref-picker__list" aria-label="Project images">{#each rows as ref (ref.id)}<button type="button" aria-pressed={ref.id===id} onclick={()=>{id=ref.id;oninspect?.(ref.id)}}><span>{ref.subjectName??ref.subject?.kind??'Reference'}</span><strong title={ref.label}>{ref.label}</strong>{#if selected.some(s=>s.referenceId===ref.id)}<small>Included</small>{/if}</button>{/each}{#if !rows.length}<p>No matching images.</p>{/if}</div></div>
   <div class="ui-ref-picker__detail">{#if current}<div class="ui-ref-picker__media">{#if imageURLs[current.id]}<img src={imageURLs[current.id]} alt={current.label} />{:else}<Icon name="image" /><p>Reading reference…</p>{/if}</div><div class="ui-ref-picker__context"><strong>{current.label}</strong><p>Choose what this image must preserve. Matching identity keeps the depicted subject’s physical design; style transfers only the visual treatment.</p><div class="ui-ref-picker__roles">{#each current.roles??['style'] as role (role)}<Button variant={role==='identity'?'primary':'secondary'} icon={role==='identity'?'link':role==='style'?'paint-brush':'image'} onclick={()=>onchoose?.(current.id,role)}>{roleLabel[role]??role}</Button>{/each}</div></div>{:else}<div class="ui-ref-picker__empty"><Icon name="images" /><p>Select an image to inspect its reference roles.</p></div>{/if}</div>
  </div>
 </DialogContent></Positioner>
 </Portal>
</Root>
<style>
 :global(.ui-ref-picker__backdrop){position:fixed;inset:0;z-index:1000;background:color-mix(in oklab,var(--surface-base) 60%,transparent);backdrop-filter:blur(12px)}:global(.ui-ref-picker__positioner){position:fixed;inset:0;z-index:1001;display:flex;align-items:center;justify-content:center;padding:var(--spacing-lg);pointer-events:none}:global(.ui-ref-picker__dialog){pointer-events:auto;width:min(1200px,calc(100vw - 48px));height:min(860px,calc(100dvh - 48px));display:flex;flex-direction:column;border:1px solid var(--border-default);border-radius:var(--radius-sm);background:color-mix(in oklab,var(--surface-raised) 96%,transparent);backdrop-filter:blur(18px);color:var(--text-primary);overflow:hidden}.ui-ref-picker__header{display:flex;align-items:center;justify-content:space-between;padding:var(--spacing-sm) var(--spacing-md);border-bottom:1px solid var(--border-default)}:global(.ui-ref-picker__title){font-size:var(--heading-md-size);font-weight:600}.ui-ref-picker__body{flex:1;min-height:0;display:grid;grid-template-columns:280px minmax(0,1fr)}.ui-ref-picker__library{display:flex;flex-direction:column;min-height:0;padding:var(--spacing-sm);border-right:1px solid var(--border-default);gap:var(--spacing-sm)}.ui-ref-picker__library input{padding:var(--spacing-xs) var(--spacing-sm);background:var(--surface-base);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:var(--text-primary);font:inherit;min-width:0}.ui-ref-picker__list{overflow:auto;display:flex;flex-direction:column;gap:var(--spacing-2xs)}.ui-ref-picker__list button{display:flex;flex-direction:column;gap:var(--spacing-2xs);text-align:left;padding:6px 8px;color:var(--text-primary);background:transparent;border:1px solid transparent;border-radius:0;cursor:pointer}.ui-ref-picker__list button[aria-pressed=true]{background:var(--surface-raised);border-color:var(--border-focus)}.ui-ref-picker__list button span,.ui-ref-picker__list small{font-size:var(--caption-size);color:var(--text-secondary)}.ui-ref-picker__list strong{font-size:var(--data-md-size);font-weight:500;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}.ui-ref-picker__detail{display:flex;flex-direction:column;min-height:0;min-width:0}.ui-ref-picker__media{flex:1;min-height:0;padding:var(--spacing-sm);display:grid;place-items:center;background:var(--surface-base)}.ui-ref-picker__media img{width:100%;height:100%;object-fit:contain;min-height:0}.ui-ref-picker__context{padding:var(--spacing-md);border-top:1px solid var(--border-default);font-size:var(--body-md-size)}.ui-ref-picker__context p{color:var(--text-secondary);font-size:var(--caption-size);line-height:1.5}.ui-ref-picker__roles{display:flex;flex-wrap:wrap;gap:var(--spacing-sm)}.ui-ref-picker__empty{display:grid;place-content:center;justify-items:center;flex:1;gap:var(--spacing-sm);color:var(--text-secondary);font-size:var(--body-md-size)}
</style>
